CREATE TABLE users(id BIGSERIAL PRIMARY KEY,username VARCHAR(32) UNIQUE NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE rooms(id BIGSERIAL PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL,created_by BIGINT REFERENCES users(id));
CREATE TABLE room_members(room_id BIGINT REFERENCES rooms(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(room_id,user_id));
CREATE TABLE messages(id BIGSERIAL PRIMARY KEY,room_id BIGINT REFERENCES rooms(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,body VARCHAR(2000) NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX idx_messages_room ON messages(room_id,created_at DESC);
GRANT pg_monitor TO chat_app;
